effect.shader:
// O `_PostExposure` do Node, calculado na CPU como lá (`GradacaoDoNode.posExposicao`).
uniform float gradacaoPosExposicao;

// k/255 pelo mais perto, montado nos bits do float (ver `node-manga.xml`).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

vec3 oitoBits3(vec3 k) {
    return vec3(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b));
}

vec3 linear(vec3 c) {
    return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c));
}

vec3 srgb(vec3 l) {
    l = clamp(l, 0.0, 1.0);
    return mix(l * 12.92, 1.055 * pow(l, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), l));
}

vec3 bytesSrgb(vec3 l) {
    return floor(srgb(l) * 255.0 + 0.5);
}

vec4 texelDePe(highp sampler2D img) {
    ivec2 T = textureSize(img, 0);
    ivec2 p = ivec2(min(floor(acScreenNorm * vec2(T)), vec2(T) - 1.0));
    if (acEntradaDePe != 1) p.y = T.y - 1 - p.y;
    return texelFetch(img, p, 0);
}

// `NodeVideo/RenderCommand/color_grading`, conta por conta (o `_SourceTex` é o `camadaRt`, o `_Lut3D` a `gradacao`).
// `_lut_space` = 0 (a LUT interna, em LogC), `_Lut3D_Params` = (1/33, 32), `_blend` = 1, sem a máscara interna.
vec4 colorGrading(vec2 vs_TEXCOORD0) {
    const float _blend = 1.0;
    const vec2 _Lut3D_Params = vec2(1.0 / 33.0, 32.0);
    float _PostExposure = gradacaoPosExposicao;
    vec4 u_xlat0;
    vec4 u_xlat1;
    vec4 u_xlat2;
    float u_xlat20;
    u_xlat0 = texture(camadaRt, vs_TEXCOORD0.xy);
    u_xlat2.xyz = u_xlat0.xyz * vec3(5.55555582, 5.55555582, 5.55555582) + vec3(0.0479959995, 0.0479959995, 0.0479959995);
    u_xlat2.xyz = log2(u_xlat2.xyz);
    u_xlat2.yzw = u_xlat2.xyz * vec3(0.0734997839, 0.0734997839, 0.0734997839) + vec3(0.386036009, 0.386036009, 0.386036009);
    u_xlat2.yzw = clamp(u_xlat2.yzw, 0.0, 1.0);
    u_xlat2.x = u_xlat0.w * _PostExposure;
    u_xlat1 = u_xlat2.yzwx;
    u_xlat2.xyz = u_xlat1.xyz * _Lut3D_Params.yyy;
    u_xlat20 = _Lut3D_Params.x * 0.5;
    u_xlat2.xyz = u_xlat2.xyz * _Lut3D_Params.xxx + vec3(u_xlat20);
    u_xlat2.xyz = texture(gradacao, u_xlat2.xyz).xyz;
    u_xlat1.xyz = u_xlat2.xyz;
    u_xlat1 = (-u_xlat0) + u_xlat1;
    u_xlat1 = vec4(_blend) * u_xlat1 + u_xlat0;
    return u_xlat1;
}

void main() {
    if (acPass == 0) {
        // A camada como o RT dela no Node: a cor em luz linear vezes o alfa, de pé; a GPU guarda em sRGB.
        vec4 c = texelDePe(inputImg);
        fragColor = vec4(linear(c.rgb) * c.a, c.a);
        return;
    }
    if (acPass == 1) {
        // O RT da camada está de pé: o UV do Node é o da tela, nos dois casos.
        vec4 o = colorGrading(acScreenNorm);
        // O alvo de 8 bits prende a saída a 0..1 antes da mistura.
        o = clamp(o, 0.0, 1.0);
        // `Blend SrcAlpha Zero` no RT sRGB: a cor vezes o alfa (em linear) e o alfa vezes ele mesmo.
        fragColor = vec4(o.rgb * o.a, o.a * o.a);
        return;
    }

    // Os bytes do RT de saída do Node, de volta à orientação da entrada e ao alfa reto do Nova.
    vec4 o = texelDePe(saidaRt);
    vec3 kc = bytesSrgb(o.rgb);
    float ka = floor(o.a * 255.0 + 0.5);
    if (ka <= 0.0) {
        fragColor = vec4(0.0);
        return;
    }
    if (ka >= 255.0) {
        fragColor = vec4(oitoBits3(kc), 1.0);
        return;
    }
    float a = oitoBits(ka);
    fragColor = vec4(srgb(min(linear(oitoBits3(kc)) / a, vec3(1.0))), a);
}
